const B = "/assets/konjed";

/** AVIF widths generated by scripts/optimize-assets.mjs, per plate (keyed by the full-size .webp). */
const L = [640, 960, 1280, 1536, 1920, 2560];
const AVIF_WIDTHS: Record<string, number[]> = {
  [`${B}/world/hero-world.webp`]: L, [`${B}/arcade/arcade-hall.webp`]: L, [`${B}/school/school-castle.webp`]: L,
  [`${B}/showcase/showcase-gallery-night.webp`]: [640, 960, 1280, 1536, 1920, 2400], [`${B}/world/final-sunset-world.webp`]: [640, 960, 1280, 1536, 1920, 2400],
  [`${B}/world/castle-sky-world.webp`]: [640, 960, 1280, 1536, 1920, 2400], [`${B}/school/school-interior.webp`]: [640, 960, 1280, 1536, 1920, 2400],
  [`${B}/school/school-people.webp`]: [640, 960, 1280, 1536, 1920, 2000],
};
/** Full-size width of each plate's WebP (fallback srcset). */
export const plateW = (full: string) => ({ [`${B}/world/hero-world.webp`]: 3000, [`${B}/arcade/arcade-hall.webp`]: 3000, [`${B}/school/school-castle.webp`]: 2600 } as Record<string, number>)[full] ?? 2400;
/** `foo.webp` → `foo-1280.avif 1280w, …` (empty when no ladder exists). */
export const avifSrcSet = (full: string) => (AVIF_WIDTHS[full] ?? []).map((w) => `${full.replace(/\.webp$/, `-${w}.avif`)} ${w}w`).join(", ");

/** `foo.webp` → responsive pair `foo-sm.webp` (1280w) + `foo.webp` (full). */
export const srcSet = (full: string, fullW = 2400) => fullW > 1920 ? `${full.replace(/\.webp$/, "-sm.webp")} 1280w, ${full.replace(/\.webp$/, "-md.webp")} 1920w, ${full} ${fullW}w` : `${full.replace(/\.webp$/, "-sm.webp")} 1280w, ${full} ${fullW}w`;

